from httpbin.core import app
client = app.test_client()

def test_get_cookies_response_json_structure_has_cookies_key_not_other_keys():
    r = client.get('/cookies', headers={'Cookie': 'x=1'})
    assert r.status_code == 200
    data = r.get_json()
    assert set(data.keys()) == {'cookies'}
    assert data['cookies'] == {'x': '1'}

test_get_cookies_response_json_structure_has_cookies_key_not_other_keys()

from httpbin.core import app
client = app.test_client()

def test_get_cookies_boundary_zero_vs_one_cookie_state_transition():
    r0 = client.get('/cookies')
    assert r0.status_code == 200
    d0 = r0.get_json()
    assert d0['cookies'] == {}
    r1 = client.get('/cookies', headers={'Cookie': 'k=v'})
    assert r1.status_code == 200
    d1 = r1.get_json()
    assert d1['cookies'] == {'k': 'v'}
    assert d1['cookies'] != {}

test_get_cookies_boundary_zero_vs_one_cookie_state_transition()
